export const CreateObjectView = observer(({ model }: { model: CreateObjectModel }) => {
  return (
    <div>
      <label htmlFor="asset-select">Asset:</label>
      <select id="asset-select" onChange={(event) => model.handleAssetChange(event)}>
        <option value="">Select an asset</option>
        {model.availableAssets.map((asset, index) => (
          <option key={index} value={asset}>
            {asset}
          </option>
        ))}
      </select>
      <button
        onClick={() => {
          if (model.selectedAsset) {
            model.createObject(model.selectedAsset).then(() => model.setSelectedAsset(null));
          }
        }}
      >
        Add Object
      </button>
      <button onClick={model.cleanupScene}>Cleanup scene</button>
    </div>
  );
});
```

In the example above, we added an ID "asset-select" to the select element for better accessibility purposes, but you can choose any descriptive name you prefer. Additionally, I added keys to the option elements to ensure React can efficiently update the list when new assets are available.

